using System.Diagnostics;
using System.Text.Json;
using System.Text.Json.Serialization;
using Gallery.Core.Images;

namespace Gallery.Web.Ui;

/// <summary>
/// Fixture photos for the /ui/ pages, loaded once from wwwroot/samples/samples.json
/// (generated by scripts/build-samples.sh; never edited by hand).
/// </summary>
public sealed class SampleCatalog
{
    public const string ManifestPath = "samples/samples.json";

    public SampleCatalog(IWebHostEnvironment env, ILogger<SampleCatalog> log)
    {
        var start = Stopwatch.GetTimestamp();
        var file = env.WebRootFileProvider.GetFileInfo(ManifestPath);
        if (!file.Exists)
            throw new FileNotFoundException("Sample manifest missing; run scripts/build-samples.sh", ManifestPath);

        using var stream = file.CreateReadStream();
        var manifest = JsonSerializer.Deserialize<Manifest>(stream, JsonOptions)
                       ?? throw new InvalidDataException("Empty sample manifest");

        var byRole = manifest.Photos.Select(p => (p.Role, Image: p.ToImageView())).ToList();
        All = byRole.Select(x => x.Image).ToList();
        Landscape = byRole.Where(x => x.Role == "landscape").Select(x => x.Image).ToList();
        Portrait = byRole.Where(x => x.Role == "portrait").Select(x => x.Image).ToList();
        Square = byRole.Single(x => x.Role == "square").Image;
        Panorama = byRole.Single(x => x.Role == "panorama").Image;
        PartialExifPortrait = Portrait.First(p => p.Exif is { Lens: null });

        log.LogInformation("op.timing {op} {duration_ms} {outcome}",
            "startup.sample-catalog", Math.Round(Stopwatch.GetElapsedTime(start).TotalMilliseconds, 2), "ok");
    }

    public IReadOnlyList<ImageView> All { get; }
    public IReadOnlyList<ImageView> Landscape { get; }
    public IReadOnlyList<ImageView> Portrait { get; }
    public ImageView Square { get; }
    public ImageView Panorama { get; }

    /// <summary>The portrait whose fixture EXIF is partial (camera and ISO only).</summary>
    public ImageView PartialExifPortrait { get; }

    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNameCaseInsensitive = true,
        NumberHandling = JsonNumberHandling.AllowReadingFromString,
    };

    private sealed record Manifest(List<Photo> Photos);

    private sealed record Photo(
        string Id, string Role, string Title, int Width, int Height,
        List<PhotoVariant> Variants, string Placeholder, string DominantColor, PhotoExif? Exif)
    {
        public ImageView ToImageView() => new(
            Id, Title, Width, Height,
            Variants.OrderBy(v => v.Width).Select(v => new Variant(v.Width, v.Avif, v.Webp)).ToList(),
            Placeholder, DominantColor,
            Exif is null ? null : new Exif(
                Exif.Make, Exif.Model, Exif.Lens, Exif.FocalLengthMm, Exif.FocalLength35Mm,
                Exif.FNumber, Exif.ExposureSeconds, Exif.Iso));
    }

    private sealed record PhotoVariant(int Width, string Avif, string Webp);

    private sealed record PhotoExif(
        string? Make, string? Model, string? Lens, decimal? FocalLengthMm, int? FocalLength35Mm,
        decimal? FNumber, decimal? ExposureSeconds, int? Iso);
}
